query:
-- Syria SKUs
SELECT COUNT(*) as syria_sku_count FROM skus WHERE country = 'Syria';

-- Syria periods
SELECT COUNT(*) as syria_period_count FROM periods WHERE country = 'Syria';

-- Syria forecast data rows
SELECT COUNT(*) as forecast_rows FROM forecast_data fd 
JOIN skus s ON fd.sku_id = s.id WHERE s.country = 'Syria';

-- Syria IMS data rows
SELECT COUNT(*) as ims_rows FROM ims_data id2 
JOIN skus s ON id2.sku_id = s.id WHERE s.country = 'Syria';

-- Syria shipment data rows
SELECT COUNT(*) as shipment_rows FROM shipment_data sd 
JOIN skus s ON sd.sku_id = s.id WHERE s.country = 'Syria';

-- Syria arrival data rows
SELECT COUNT(*) as arrival_rows FROM arrival_data ad 
JOIN skus s ON ad.sku_id = s.id WHERE s.country = 'Syria';

